"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
// Массив содержащий все поддерживаемые методы решения капч
const supportedMethods = ["userrecaptcha", "hcaptcha", "geetest", "geetest_v4", "yandex", "funcaptcha", "lemin", "amazon_waf", "turnstile", "base64"];
const recaptchaRequiredFields = ['pageurl', 'googlekey'];
const hcaptchaRequiredFields = ['pageurl', 'sitekey'];
const geetestRequiredFields = ['pageurl', 'gt', 'challenge'];
const geetestV4RequiredFields = ['pageurl', 'captcha_id'];
const yandexSmartRequiredFields = ['pageurl', 'sitekey'];
const funCaptchaRequiredFields = ['pageurl', 'publickey'];
const leminRequiredFields = ['pageurl', 'div_id', 'captcha_id'];
const amazonWafRequiredFields = ['pageurl', 'context', 'iv', 'sitekey'];
const turnstileRequiredFields = ['pageurl', 'sitekey'];
const imageCaptchaRequiredFields = ['base64image'];
/**
 * Функия получения обязательных аргументов для капчи.
 *
 * @param {string} method Принимает метод решения капчи.
 * @returns {Array} Возвращает массив содержащий обязательные аргументы для данной капчи.
 */
const getRequiredFildsArr = (method) => {
    let requiredFieldsArr = ['pageurl'];
    switch (method) {
        case "userrecaptcha":
            requiredFieldsArr = recaptchaRequiredFields;
            break;
        case "hcaptcha":
            requiredFieldsArr = hcaptchaRequiredFields;
            break;
        case "geetest":
            requiredFieldsArr = geetestRequiredFields;
            break;
        case "geetest_v4":
            requiredFieldsArr = geetestV4RequiredFields;
            break;
        case "yandex":
            requiredFieldsArr = yandexSmartRequiredFields;
            break;
        case "funcaptcha":
            requiredFieldsArr = funCaptchaRequiredFields;
            break;
        case "lemin":
            requiredFieldsArr = leminRequiredFields;
            break;
        case "amazon_waf":
            requiredFieldsArr = amazonWafRequiredFields;
            break;
        case "turnstile":
            requiredFieldsArr = turnstileRequiredFields;
            break;
        case "base64":
            requiredFieldsArr = imageCaptchaRequiredFields;
            break;
    }
    return requiredFieldsArr;
};
/**
* +recaptcha  method: "userrecaptcha",
* +hcaptcha method: "hcaptcha",
* +geetest method: "geetest",
* +geetestV4 method: "geetest_v4",
* +yandexSmart method: "yandex",
* +funCaptcha method: "funcaptcha",
* +lemin method: "lemin",
* +amazonWaf method: "amazon_waf",
* +cloudflareTurnstile   method: "turnstile",
* imageCaptcha method: "base64" с этим по сложнее будет, надо отдельное что-то запилить
* @param { Object | Array } params Параметры капчи которые необходимо проверить. Для imageCaptcha это значение  тоже объект, но другой(объект arguments) -  массив Arguments, для остальных капч `Object`.
* @returns true | false | Error
* @example
* checkCaptchaParams({
*   pageurl: "https://2captcha.com/demo/hcaptcha?difficulty=moderate",
*   sitekey: "b76cd927-d266-4cfb-a328-3b03ae07ded6"
* }, 'userrecaptcha')
*/
function checkCaptchaParams(params, method) {
    // console.log("arguments: ")
    // console.log(arguments)
    let isCorrectCaptchaParams;
    const isIncorrectCaptchaMethod = !supportedMethods.includes(method);
    const isImageCaptchaMethod = method === "base64";
    if (isIncorrectCaptchaMethod) {
        isCorrectCaptchaParams = false;
        throw new Error(`Error when check params captcha.\n Not found "${method}" method in the "captchasRequiredFields" Object.\n `);
    }
    // if(isImageCaptchaMethod) {
    console.log(typeof (params));
    console.log("params:");
    console.log(params);
    console.log("------------");
    //   //FixMe: запилить проверку для капчи картинки
    // }
    const requiredFields = getRequiredFildsArr(method);
    console.log("requiredFields: ");
    console.log(requiredFields);
    requiredFields.forEach(fieldName => {
        const isThisFieldNotAvailable = !params.hasOwnProperty(fieldName);
        // console.log(params[fieldName])
        // const test = params.base64image
        if (isThisFieldNotAvailable) {
            isCorrectCaptchaParams = false;
            let errorMessage;
            if (isImageCaptchaMethod) {
                errorMessage = `Error when check params image captcha.\n Not found "${fieldName}" param. Param "${fieldName}" is required for "${method}" method. Please add param "${fieldName}" and try again.`;
            }
            else {
                errorMessage = `Error when check params captcha.\n Not found "${fieldName}" field in the Object. Field "${fieldName}" is required for "${method}" method. Please add field "${fieldName}" and try again.`;
            }
            throw new Error(errorMessage);
        }
        else {
            isCorrectCaptchaParams = true;
        }
    });
    // console.log("isObject: "+ isObject)
    console.log("isIncorrectCaptchaMethod: " + isIncorrectCaptchaMethod);
    return isCorrectCaptchaParams;
}
exports.default = checkCaptchaParams;
